export function getLocalConnections(userId?: string): ConnectionWithProfile[] {
    try {
        if (typeof window === 'undefined') return [];
        const isRounak = userId === '794703c5-c695-47bc-864c-60f400ab6fbe' || userId === 'rounak2';
        const storageKey = userId ? `knock_local_connections_${userId}` : 'knock_local_connections';
        const stored = localStorage.getItem(storageKey);
        if (stored) {
            let parsed = JSON.parse(stored);
            if (Array.isArray(parsed) && parsed.length > 0) {
                return parsed;
            }
        }
        if (isRounak) {
            try {
                localStorage.setItem(storageKey, JSON.stringify(SEED_CONNECTIONS));
            } catch (_) {}
            return SEED_CONNECTIONS;
        }
        return [];
    } catch (_) {}
    return [];
}


export function removeLocalConnection(connectionId: string): void {
    try {
        if (typeof window === 'undefined') return;
        const current = getLocalConnections();
        const updated = current.filter(c => c.id !== connectionId);
        localStorage.setItem('knock_local_connections', JSON.stringify(updated));
    } catch (_) {}
}

export function bumpLocalConnectionStreak(connectionId: string): number {
    try {
        if (typeof window === 'undefined') return 1;
        const current = getLocalConnections();
        let newStreak = 1;
        const updated = current.map(c => {
            if (c.id === connectionId) {
                newStreak = (c.streak_count || 1) + 1;
                return {
                    ...c,
                    streak_count: newStreak,
                    streakStatus: 'active' as const,
                    last_interaction_at: new Date().toISOString()
                };
            }
            return c;
        });
        localStorage.setItem('knock_local_connections', JSON.stringify(updated));
        return newStreak;
    } catch (_) {
        return 1;
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// LOCAL POST PERSISTENCE HELPERS
// ─────────────────────────────────────────────────────────────────────────────

const STORAGE_KEY = 'knock_local_posts_v7';
const DELETED_POSTS_KEY = 'knock_deleted_post_ids_v1';
const FAKE_ACCOUNTS = new Set(['bollywood_superstars', 'baklol_kumar', 'meme_hub_insta', 'epic_fun_page', 'relatable_postss']);
const SEED_POST_IDS = new Set(SEED_POSTS.map(s => s.id));

// ⚡ In-memory cache so getLocalPosts() executes in O(1) without synchronous JSON.parse / localStorage.setItem on every read
let _localPostsCache: PostData[] | null = null;
let _deletedPostIdsCache: Set<string> | null = null;

export function getDeletedPostIds(): Set<string> {
    if (_deletedPostIdsCache) return _deletedPostIdsCache;
    _deletedPostIdsCache = new Set<string>();
    if (typeof window === 'undefined') return _deletedPostIdsCache;
    try {
        const raw = localStorage.getItem(DELETED_POSTS_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                parsed.forEach(id => {
                    if (id !== undefined && id !== null) {
                        _deletedPostIdsCache!.add(String(id));
                    }
                });
            }
        }
    } catch (_) {}
    return _deletedPostIdsCache;
}

export function registerCloudDeletedIds(ids: string[]): void {
    if (!ids || ids.length === 0) return;
    const deleted = getDeletedPostIds();
    let changed = false;
    for (const id of ids) {
        if (id && !deleted.has(String(id))) {
            deleted.add(String(id));
            changed = true;
        }
    }
    if (changed && typeof window !== 'undefined') {
        try {
            localStorage.setItem(DELETED_POSTS_KEY, JSON.stringify(Array.from(deleted)));
        } catch (_) {}
        if (_localPostsCache) {
            _localPostsCache = _localPostsCache.filter(p => !isPostDeletedLocally(p.id, p.image_url));
        }
    }
}

export function isStockOrSharedMediaUrl(cleanUrl: string): boolean {
    if (!cleanUrl) return true;
    const lower = cleanUrl.toLowerCase();
    return (
        lower.includes('images.unsplash.com') ||
        lower.includes('videos.pexels.com') ||
        lower.includes('images.pexels.com') ||
        lower.includes('assets.mixkit.co') ||
        lower.includes('cdn.coverr.co') ||
        lower.includes('w3schools.com') ||
        lower.includes('media.w3.org') ||
        lower.includes('vjs.zencdn.net') ||
        lower.includes('mdn.mozilla.net') ||
        lower.includes('mdn.github.io') ||
        lower.includes('cdn.plyr.io') ||
        lower.includes('test-videos.co.uk') ||
        lower.includes('/videos/sonambajwa')
    );
}

export function isPostDeletedLocally(postId?: string | number | null, imageUrl?: string | null): boolean {
    const deleted = getDeletedPostIds();
    if (postId !== undefined && postId !== null) {
        const rawStr = String(postId);
        const cleanStr = rawStr.replace(/_p\d+_\d+$/, '');
        if (deleted.has(rawStr) || deleted.has(cleanStr)) return true;
    }
    if (imageUrl && typeof imageUrl === 'string' && !imageUrl.includes('#REMAP')) {
        const cleanUrl = imageUrl.split('#')[0].split('?')[0].trim();
        if (cleanUrl && !isStockOrSharedMediaUrl(cleanUrl)) {
            if (deleted.has(cleanUrl)) return true;
            const fileName = cleanUrl.split('/').pop() || '';
            if (fileName.length > 16 && /\d{10,}/.test(fileName) && deleted.has(fileName)) return true;
        }
    }
    return false;
}

export function removeLocalPost(postId: string | number, imageUrl?: string | null): void {
    try {
        if (typeof window === 'undefined') return;
        const rawStr = String(postId);
        const cleanStr = rawStr.replace(/_p\d+_\d+$/, '');
        const deleted = getDeletedPostIds();
        deleted.add(rawStr);
        deleted.add(cleanStr);
        if (imageUrl && typeof imageUrl === 'string' && !imageUrl.includes('#REMAP')) {
            const cleanUrl = imageUrl.split('#')[0].split('?')[0].trim();
            if (cleanUrl && !isStockOrSharedMediaUrl(cleanUrl)) {
                deleted.add(cleanUrl);
                const fileName = cleanUrl.split('/').pop() || '';
                if (fileName.length > 16 && /\d{10,}/.test(fileName)) {
                    deleted.add(fileName);
                }
            }
        }
        try {
            localStorage.setItem(DELETED_POSTS_KEY, JSON.stringify(Array.from(deleted)));
        } catch (_) {}

        const posts = getLocalPosts();
        const updated = posts.filter(p => String(p.id) !== rawStr && String(p.id) !== cleanStr && !isPostDeletedLocally(p.id, p.image_url));
        persistLocalPosts(updated);

        // Also remove from knock_local_stories if present
        try {
            const storedStories = localStorage.getItem('knock_local_stories');
            if (storedStories) {
                const parsedStories = JSON.parse(storedStories);
                if (Array.isArray(parsedStories)) {
                    const filteredStories = parsedStories.filter((s: any) => s && String(s.id) !== rawStr && String(s.id) !== cleanStr);
                    localStorage.setItem('knock_local_stories', JSON.stringify(filteredStories));
                }
            }
        } catch (_) {}
    } catch (_) {}
}

function persistLocalPosts(posts: PostData[]): void {
    _localPostsCache = posts;
    if (typeof window === 'undefined') return;

    const writePrimary = (list: PostData[]) => {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
    };

    try {
        // Free redundant legacy keys first so user posts are not duplicated across localStorage quota
        for (const legacyKey of ['knock_local_posts_v6', 'knock_local_posts_v5', 'knock_local_posts_v4', 'knock_local_posts']) {
            try { localStorage.removeItem(legacyKey); } catch (_) {}
        }
        writePrimary(posts);
    } catch (_) {
        // Recover from QuotaExceededError by clearing disposable feed caches, then trimming oversized data-URL posters
        try {
            for (let i = localStorage.length - 1; i >= 0; i--) {
                const k = localStorage.key(i);
                if (k && (k.startsWith('knock_home_posts_cache') || k.startsWith('knock_explore_') || k.startsWith('knock_boost_stories_cache'))) {
                    localStorage.removeItem(k);
                }
            }
            writePrimary(posts);
            return;
        } catch (_) {}

        try {
            const compacted = posts.map(p => {
                if (!p.image_url || !p.image_url.includes('#POSTER:data%3A')) return p;
                return { ...p, image_url: p.image_url.replace(/#POSTER:data%3A[^#]+/g, '') };
            });
            _localPostsCache = compacted;
            writePrimary(compacted);
        } catch (_) {}
    }
}

export function getLocalPosts(): PostData[] {
    if (_localPostsCache) {
        return _localPostsCache.filter(p => !isPostDeletedLocally(p.id, p.image_url));
    }
    try {
        if (typeof window === 'undefined') return [];
        // Merge across current and legacy storage keys so older user posts are never hidden by an empty newer key
        const keys = [
            STORAGE_KEY,
            'knock_local_posts_v6',
            'knock_local_posts_v5',
            'knock_local_posts_v4',
            'knock_local_posts',
        ];
        const mergedById = new Map<string, PostData>();
        for (const key of keys) {
            const raw = localStorage.getItem(key);
            if (!raw) continue;
            try {
                const parsed = JSON.parse(raw);
                if (!Array.isArray(parsed)) continue;
                for (const p of parsed) {
                    if (!p || !p.id || !p.image_url) continue;
                    if (isPostDeletedLocally(p.id, p.image_url)) continue;
                    const idStr = String(p.id);
                    if (idStr.startsWith('story-') || idStr.startsWith('seed-') || idStr.startsWith('reel-')) continue;
                    if (FAKE_ACCOUNTS.has(p.username) || SEED_POST_IDS.has(idStr)) continue;
                    if (!mergedById.has(idStr)) {
                        mergedById.set(idStr, p);
                    }
                }
            } catch (_) {}
        }
        const cleaned = Array.from(mergedById.values());
        _localPostsCache = cleaned;
        if (cleaned.length > 0) {
            persistLocalPosts(cleaned);
        }
        return cleaned;
    } catch (_) {}

    _localPostsCache = [];
    return [];
}

export function saveLocalPost(post: PostData): void {
    try {
        if (typeof window === 'undefined') return;
        const posts = getLocalPosts();
        const updated = [post, ...posts.filter(p => p.id !== post.id)];
        persistLocalPosts(updated);
    } catch (_) {}
}

export function updateLocalPostLikes(postId: string, delta: number): void {
    try {
        if (typeof window === 'undefined') return;
        const posts = getLocalPosts();
        const updated = posts.map(p => {
            if (p.id === postId) {
                return { ...p, likes_count: Math.max(0, (p.likes_count || 0) + delta) };
            }
            return p;
        });
        persistLocalPosts(updated);
    } catch (_) {}
}

export function isPostLikedLocally(postId: string | number, userId?: string): boolean {
    try {
        if (typeof window === 'undefined') return false;
        const pIdStr = String(postId);
        const likes = getLocalLikes();
        if (userId && likes[`${userId}_${pIdStr}`]) return true;
        return !!likes[pIdStr];
    } catch (_) {
        return false;
    }
}

export function getLocalLikes(): Record<string, boolean> {
    try {
        if (typeof window === 'undefined') return {};
        const raw = localStorage.getItem('knock_local_likes');
        return raw ? JSON.parse(raw) : {};
    } catch (_) {
        return {};
    }
}

export function toggleLocalLike(postId: string | number, userId?: string): boolean {
    try {
        if (typeof window === 'undefined') return true;
        const pIdStr = String(postId);
        const likes = getLocalLikes();
        const userKey = userId ? `${userId}_${pIdStr}` : `guest_${pIdStr}`;
        const isCurrentlyLiked = !!(likes[userKey] || likes[pIdStr]);
        const newStatus = !isCurrentlyLiked;
        
        if (newStatus) {
            likes[userKey] = true;
            likes[pIdStr] = true;
        } else {
            delete likes[userKey];
            delete likes[pIdStr];
        }
        localStorage.setItem('knock_local_likes', JSON.stringify(likes));
        updateLocalPostLikes(pIdStr, newStatus ? 1 : -1);
        return newStatus;
    } catch (_) {
        return true;
    }
}

export function updateLocalPostComments(postId: string | number, delta: number): void {
    try {
        if (typeof window === 'undefined') return;
        const pIdStr = String(postId);
        const posts = getLocalPosts();
        const updated = posts.map(p => {
            if (String(p.id) === pIdStr) {
                return { ...p, comments_count: Math.max(0, (p.comments_count || 0) + delta) };
            }
            return p;
        });
        persistLocalPosts(updated);
    } catch (_) {}
}

export function getLocalComments(postId: string | number): CommentData[] {
    try {
        if (typeof window === 'undefined') return [];
        const pIdStr = String(postId);
        const raw = localStorage.getItem(`knock_comments_${pIdStr}`);
        return raw ? JSON.parse(raw) : [];
    } catch (_) {
        return [];
    }
}

export function saveLocalComment(comment: CommentData): void {
    try {
        if (typeof window === 'undefined') return;
        const pIdStr = String(comment.post_id);
        const comments = getLocalComments(pIdStr);
        const exists = comments.some(c => c.id === comment.id);
        const updated = exists ? comments : [comment, ...comments];
        localStorage.setItem(`knock_comments_${pIdStr}`, JSON.stringify(updated));
        updateLocalPostComments(pIdStr, 1);
    } catch (_) {}
}

export function deleteLocalComment(commentId: string, postId: string | number): void {
    try {
        if (typeof window === 'undefined') return;
        const pIdStr = String(postId);
        const comments = getLocalComments(pIdStr);
        const updated = comments.filter(c => c.id !== commentId);
        localStorage.setItem(`knock_comments_${pIdStr}`, JSON.stringify(updated));
        updateLocalPostComments(pIdStr, -1);
    } catch (_) {}
}


