export function remapDeadSupabaseUrl(url?: string, id?: string, mediaType?: string): string {
    if (!url || typeof url !== 'string') return url || '';
    if (!url.includes('ktruosvlqnpcuzayrqkk.supabase.co')) return url;
    const key = String(id || url);
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
        hash = ((hash << 5) - hash + key.charCodeAt(i)) | 0;
    }
    const idx = Math.abs(hash);
    const isVid = mediaType === 'video' || /\.(mp4|webm|mov|m4v)(?:[?#]|$)/i.test(url) || url.includes('#video.mp4');
    if (isVid) {
        // Prefer spare tail slots (beyond initial SEED_POSTS video count) and tag #REMAP so deduplicatePosts keeps distinct IDs
        const basePool = FALLBACK_VIDEO_POOL;
        const picked = basePool.length > 160
            ? basePool[160 + (idx % (basePool.length - 160))]
            : basePool[idx % basePool.length];
        return picked.includes('#REMAP') ? picked : `${picked}#REMAP`;
    }
    const photoPool = FALLBACK_PHOTO_POOL;
    const picked = photoPool.length > 115
        ? photoPool[115 + (idx % (photoPool.length - 115))]
        : photoPool[idx % photoPool.length];
    return picked.includes('#REMAP') ? picked : `${picked}#REMAP`;
}
